60	fn build_router_with_options(
61	    state: Arc<AppState>,
62	    dev_mode_enabled: bool,
63	    runtime_lora_updating_enabled: bool,
64	) -> Router {
65	    let mut router = Router::new()
66	        // Health & monitoring
67	        .route("/health", get(health::health))
68	        .route("/metrics", get(metrics::scrape))
69	        .route("/load", get(load::load))
70	        .route("/version", get(version::version))
71	        // OpenAI-compatible endpoints
72	        .route("/v1/models", get(openai::list_models))
73	        .route("/v1/completions", post(openai::completions))
74	        .route("/v1/chat/completions", post(openai::chat_completions))
75	        // vLLM specific inference endpoints
76	        .route("/inference/v1/generate", post(inference::generate));
77	
78	    if runtime_lora_updating_enabled {
79	        router = router
80	            .route("/v1/load_lora_adapter", post(lora::load_lora_adapter))
81	            .route("/v1/unload_lora_adapter", post(lora::unload_lora_adapter));
82	    }
83	
84	    if dev_mode_enabled {
85	        // Development-only
86	        router = router
87	            .route("/reset_prefix_cache", post(cache::reset_prefix_cache))
88	            .route("/reset_mm_cache", post(cache::reset_mm_cache))
89	            .route("/reset_encoder_cache", post(cache::reset_encoder_cache))
90	            .route("/collective_rpc", post(collective_rpc::collective_rpc))
91	            .route("/sleep", post(sleep::sleep))
92	            .route("/wake_up", post(sleep::wake_up))
93	            .route("/is_sleeping", get(sleep::is_sleeping))
94	            .route("/pause", post(pause::pause))
95	            .route("/resume", post(pause::resume))
96	            .route("/is_paused", get(pause::is_paused))
97	            .route("/server_info", get(server_info::server_info))
98	    }
99	
100	    let enable_request_id_headers = state.enable_request_id_headers;
101	    let mut router = router
102	        .with_state(state.clone())
103	        .layer(from_fn_with_state(state, middleware::track_server_load))
104	        .layer(from_fn(middleware::track_http_metrics))
105	        .layer(TraceLayer::new_for_http());
106	
107	    if enable_request_id_headers {
108	        router = router.layer(from_fn(middleware::set_request_id_header));
109	    }
110	
111	    router
112	}
