37	/// Build the shared application state for one configured model and one engine
38	/// client.
39	async fn build_state(config: &Config) -> Result<Arc<AppState>> {
40	    // Load both backends from the same model metadata so they stay in sync.
41	    let loaded = load_model_backends(
42	        &config.model,
43	        LoadModelBackendsOptions {
44	            renderer: config.renderer,
45	            language_model_only: config.language_model_only,
46	            chat_template: config.chat_template.clone(),
47	            chat_template_content_format: config.chat_template_content_format,
48	            default_chat_template_kwargs: config
49	                .default_chat_template_kwargs
50	                .clone()
51	                .unwrap_or_default(),
52	        },
53	    )
54	    .await
55	    .context("failed to create chat/text backends")?;
56	    let text_backend = loaded.text_backend;
57	    let chat_backend = loaded.chat_backend;
58	
59	    let coordinator_mode = config.effective_coordinator_mode(text_backend.is_moe());
60	    info!(
61	        engine_count = config.engine_count(),
62	        model_is_moe = text_backend.is_moe(),
63	        ?coordinator_mode,
64	        "resolved coordinator mode"
65	    );
66	
67	    let client = EngineCoreClient::connect(EngineCoreClientConfig {
68	        transport_mode: config.transport_mode.clone(),
69	        coordinator_mode,
70	        model_name: config.model.clone(),
71	        client_index: 0,
72	    })
73	    .await
74	    .context("failed to connect to engine core")?;
75	
76	    let llm = Llm::new(client).with_log_stats(!config.disable_log_stats);
77	    let text = TextLlm::new(llm, text_backend);
78	
79	    let chat = ChatLlm::new(text, chat_backend)
80	        .with_tool_call_parser(config.tool_call_parser.clone())
81	        .with_reasoning_parser(config.reasoning_parser.clone());
82	
83	    // If no served names are specified, fall back to the backend model path so
84	    // that the API always has at least one valid model ID.
85	    let served_model_names = if config.served_model_name.is_empty() {
86	        vec![config.model.clone()]
87	    } else {
88	        config.served_model_name.clone()
89	    };
90	
91	    Ok(Arc::new(
92	        AppState::new(served_model_names, chat)
93	            .with_log_requests(config.enable_log_requests)
94	            .with_request_id_headers(config.enable_request_id_headers)
95	            .with_server_info(ServerInfoSnapshot::from_config(config)),
96	    ))
97	}
98	
99	/// Run the OpenAI-compatible HTTP server until the supplied shutdown token is
100	/// cancelled.
101	///
102	/// The server owns one `vllm-chat` facade, which in turn owns the lower
103	/// `vllm-text` and `vllm-llm` layers, and shuts them down before returning.
104	pub async fn serve(config: Config, shutdown: CancellationToken) -> Result<()> {
105	    serve_with_router_extension(config, shutdown, |router| router).await
106	}
107	
108	/// Run the OpenAI-compatible HTTP server with an opt-in router extension.
109	///
110	/// The extension receives the finalized vLLM router and can merge additional
111	/// routes before the server starts accepting requests.
112	pub async fn serve_with_router_extension<F>(
113	    config: Config,
114	    shutdown: CancellationToken,
115	    extend_router: F,
116	) -> Result<()>
117	where
118	    F: FnOnce(Router) -> Router,
119	{
120	    config.validate().context("invalid OpenAI frontend configuration")?;
121	
122	    // Also check shutdown during the (potentially long) startup handshake.
123	    let state = tokio::select! {
124	        result = build_state(&config) => result?,
125	        _ = shutdown.cancelled() => return Ok(()),
126	    };
127	    let listener = Listener::bind(&config.listener_mode)
128	        .await
129	        .context("failed to bind listener for OpenAI server")?;
130	    let bind_address = listener.local_addr()?;
131	    let model = state.primary_model_name().to_owned();
132	    let app = extend_router(build_router(state.clone()));
133	
134	    // Optionally bind the gRPC Generate server on a separate port. Bind
135	    // synchronously here so bind errors (port in use, permission denied, ...)
136	    // surface before we start serving, rather than being deferred until
137	    // shutdown. The gRPC listener follows the same host as the HTTP listener so
138	    // that enabling --grpc-port does not accidentally expose the service on all
139	    // interfaces when HTTP is intentionally local-only.
140	    let grpc_setup = if let Some(grpc_port) = config.grpc_port {
141	        let grpc_host = match &config.listener_mode {
142	            HttpListenerMode::BindTcp { host, .. } => host.as_str(),
143	            HttpListenerMode::BindUnix { .. } | HttpListenerMode::InheritedFd { .. } => "0.0.0.0",
144	        };
145	        let grpc_listener = TcpListener::bind((grpc_host, grpc_port))
146	            .await
147	            .with_context(|| format!("failed to bind gRPC listener on {grpc_host}:{grpc_port}"))?;
148	        let addr = grpc_listener.local_addr()?;
149	        let svc = grpc::GenerateServer::new(grpc::GenerateServiceImpl::new(state.clone()));
150	        info!(%addr, "starting gRPC server");
151	        Some((grpc_listener, svc))
152	    } else {
153	        None
154	    };
155	
156	    info!(%bind_address, %model, "starting OpenAI server");
157	
158	    // Set TCP_NODELAY on accepted connections to reduce latency.
159	    // By `tap_io` we will do this on every accepted connection.
160	    let listener = listener.tap_io(|io| {
161	        if let Either::Left(tcp_stream) = io
162	            && let Err(err) = tcp_stream.set_nodelay(true)
163	        {
164	            trace!(error = %err, "failed to enable TCP_NODELAY on accepted HTTP connection");
165	        }
166	    });
167	
168	    // Run HTTP and gRPC concurrently under a child token of the caller's shutdown
169	    // token. Caller cancellation propagates into both protocols; if either
170	    // protocol exits first, we cancel this child token so its sibling also
171	    // begins a graceful drain.
