use axum::Json;
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::state::AppState;

/// Route prefixes that require a valid API key when authentication is enabled.
const GUARDED_PREFIXES: &[&str] = &["/v1", "/v2", "/inference"];

/// Enforce bearer-token authentication on guarded inference and model-listing
/// routes.
///
/// Requests to paths under [`GUARDED_PREFIXES`] must present a matching
/// `Authorization: Bearer <key>` header. `OPTIONS` preflight requests and any
/// route outside the guarded prefixes (for example `/health`) are always
/// allowed through. Unauthorized requests are rejected with `401 Unauthorized`
/// and an `{"error": "Unauthorized"}` JSON body.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    request: Request,
    next: Next,
) -> Response {
    // CORS preflight requests never carry credentials; let them through.
    if request.method() == Method::OPTIONS {
        return next.run(request).await;
    }

    let path = request.uri().path();
    let is_guarded = GUARDED_PREFIXES
        .iter()
        .any(|prefix| path == *prefix || path.starts_with(&format!("{prefix}/")));
    if !is_guarded {
        return next.run(request).await;
    }

    let authorized = request
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .is_some_and(|token| state.is_valid_api_key(token));

    if authorized {
        next.run(request).await
    } else {
        (StatusCode::UNAUTHORIZED, Json(json!({ "error": "Unauthorized" }))).into_response()
    }
}
