#[serial]
async fn tmp_api_key_auth() {
    let (chat, _engine_task) = test_models_with_engine_outputs_and_backend(
        b"engine-openai-auth",
        default_stream_output_specs(),
        Arc::new(FakeChatBackend::new()),
    )
    .await;
    let app = build_router(Arc::new(
        AppState::new(vec!["Qwen/Qwen1.5-0.5B-Chat".to_string()], chat)
            .with_api_keys(vec!["secret".to_string()]),
    ));

    // Guarded route without a key -> 401 with the Unauthorized body.
    let response = app
        .clone()
        .call(
            Request::builder().uri("/v1/models").body(Body::empty()).expect("build request"),
        )
        .await
        .expect("call app");
    assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
    let body = to_bytes(response.into_body(), usize::MAX).await.expect("read body");
    assert_eq!(&body[..], br#"{"error":"Unauthorized"}"#);

    // Wrong key -> 401.
    let response = app
        .clone()
        .call(
            Request::builder()
                .uri("/v1/models")
                .header("Authorization", "Bearer nope")
                .body(Body::empty())
                .expect("build request"),
        )
        .await
        .expect("call app");
    assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

    // Valid key -> passes auth (handler responds 200).
    let response = app
        .clone()
        .call(
            Request::builder()
                .uri("/v1/models")
                .header("Authorization", "Bearer secret")
                .body(Body::empty())
                .expect("build request"),
        )
        .await
        .expect("call app");
    assert_eq!(response.status(), StatusCode::OK);

    // Unguarded route -> allowed without a key.
    let response = app
        .clone()
        .call(Request::builder().uri("/health").body(Body::empty()).expect("build request"))
        .await
        .expect("call app");
    assert_eq!(response.status(), StatusCode::OK);

    // OPTIONS on a guarded route -> not rejected by auth (no 401).
    let response = app
        .clone()
        .call(
            Request::builder()
                .method("OPTIONS")
                .uri("/v1/models")
                .body(Body::empty())
                .expect("build request"),
        )
        .await
        .expect("call app");
    assert_ne!(response.status(), StatusCode::UNAUTHORIZED);
